import { ViewTransition } from 'react'
import Link from 'next/link'
import { products } from '@/lib/products'
import { productImageName } from './transitions'

export function ProductGrid() {
  return (
    <div className="product-grid">
      {products.map((product) => (
        <Link
          key={product.slug}
          href={`/product/${product.slug}`}
          className="product-card"
          transitionTypes={['nav-forward']}
        >
          {/* Same `name` as the detail hero, so the browser morphs one into
              the other. `default="none"` keeps the other three thumbnails
              from crossfading on every unrelated transition. */}
          <ViewTransition
            name={productImageName(product.slug)}
            share="morph"
            default="none"
          >
            <div
              className="product-image"
              style={{ backgroundColor: product.color }}
            />
          </ViewTransition>
          <h2>{product.name}</h2>
          <p>${product.price}</p>
        </Link>
      ))}
    </div>
  )
}

